// Regenerates the reference block in index.js with Node as the reference
// implementation: `node gen-reference.mjs`. Keys are generated fresh, so
// every run changes the file. Deterministic answers come from running the
// fixture's own `compute` under Node; ECDSA, which is randomized, stores
// Node's signatures for the fixture to verify.
import crypto from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";

const pem = (type, options) =>
  crypto.generateKeyPairSync(type, options).privateKey.export({ type: "pkcs8", format: "pem" });
const KEYS = {
  rsa: { private: pem("rsa", { modulusLength: 2048 }) },
  ed25519: { private: pem("ed25519", {}) },
  p256: { private: pem("ec", { namedCurve: "P-256" }) },
  p384: { private: pem("ec", { namedCurve: "P-384" }) },
  p521: { private: pem("ec", { namedCurve: "P-521" }) },
};
const message = Buffer.from("celld node:crypto vector");
const ECDSA = {};
for (const curve of ["p256", "p384", "p521"]) {
  for (const hash of ["sha256", "sha384", "sha512"]) {
    ECDSA[`${curve} ${hash}`] = crypto.sign(hash, message, KEYS[curve].private).toString("base64");
  }
}

const path = new URL("./index.js", import.meta.url);
const begin = "// BEGIN REFERENCE\n";
const end = "// END REFERENCE\n";
const write = (reference) => {
  const source = readFileSync(path, "utf8");
  const block =
    `${begin}// Generated by gen-reference.mjs with Node ${process.version}. Do not edit.\n` +
    `const KEYS = ${JSON.stringify(KEYS, null, 2)};\n` +
    `const ECDSA = ${JSON.stringify(ECDSA, null, 2)};\n` +
    `const REFERENCE = ${JSON.stringify(reference, null, 2)};\n${end}`;
  writeFileSync(path, source.slice(0, source.indexOf(begin)) + block + source.slice(source.indexOf(end) + end.length));
};
// Write the keys first, so `compute` runs on the keys being stored.
write({});
const { compute } = await import(`${path.href}?keys`);
write(compute(KEYS));
